"""Fuzz illegal initial configurations and validation rejection paths."""
import json, random, sys
sys.path.insert(0, '/workspace/tmp')
import ref, harness, fuzz

def run_case(seed):
    rng = random.Random(seed)
    sess, N, G, D, templates, domains = fuzz.make_session(rng)
    txs = fuzz.make_transactions(rng, G, N, D, templates, domains, rng.randint(1, 4))
    s = ref.Session(dict(sess))
    if not s.legal():
        return None
    for tx in txs:
        if tx['revision'] == '@':
            tx['revision'] = s.revision
        else:
            tx['revision'] = s.revision + rng.randint(1, 3)
        s.transact(dict(tx))
    sess['transactions'] = [{k: tx[k] for k in ('revision', 'edits', 'query')} for tx in txs]
    mode = rng.randrange(6)
    if mode == 0 and D:
        # over-capacity node
        node = rng.randrange(N)
        sess['caps'][node] = 0
        for i in range(N):
            if i != node and sess['caps'][i] == 0:
                sess['caps'][i] = 1
    elif mode == 1 and D:
        # mixed group
        idx = rng.randrange(D)
        sess['tasks'][idx][3] = (sess['tasks'][idx][3] + 1) % 4
    elif mode == 2 and D:
        # zero quota on a nonempty group
        target = sess['tasks'][rng.randrange(D)][1]
        sess['groups'][target][0] = 0
    elif mode == 3 and D:
        # work violation by raising weight beyond quota*budget
        idx = rng.randrange(D)
        sess['tasks'][idx][2] = 10 ** 9
    elif mode == 4:
        # truncate caps
        if len(sess['caps']) > 1:
            sess['caps'] = sess['caps'][:-1]
    else:
        return None
    request = {"version": 2, "sessions": [sess]}
    expected = ref.run(request)
    p = harness.run_request(request)
    if p.returncode != 0:
        return f'seed {seed}: rc={p.returncode} {p.stderr.decode()[:300]}'
    try:
        got = harness.strict_load(p.stdout)
    except Exception as e:
        return f'seed {seed}: bad json {e}'
    if not harness.same(got, expected):
        return (f'seed {seed}: MISMATCH mode={mode}\n req={json.dumps(request)[:600]}\n'
                f' got={json.dumps(got)[:300]}\n exp={json.dumps(expected, default=str)[:300]}')
    return None

if __name__ == '__main__':
    start = int(sys.argv[1]); count = int(sys.argv[2])
    bad = 0
    for seed in range(start, start + count):
        msg = run_case(seed)
        if msg:
            print(msg); bad += 1
            if bad > 3: break
    print('done', count, 'failures', bad)
PYEOF
